    try:
        tree = ast.parse(code, filename=filename)
    except SyntaxError:
        raise

    visitor = NameCollector()
    visitor.visit(tree)

    # Filter out builtins and magic globals
    names = visitor.names - set(dir(builtins)) - MAGIC_GLOBALS

    # If we have __all__ names collected, return those
    # Note: our NameCollector already handles __all__ directly
    return names


